const WA='6288214303430';const TPL=`Halo, selamat pagi/siang, Kak. Perkenalkan, saya ingin bertanya mengenai aplikasi ProjectKita. Saya tertarik untuk mencoba dan menginstal aplikasi tersebut. Apakah boleh diinformasikan bagaimana cara mendapatkan dan menginstalnya, serta apakah ada persyaratan tertentu yang perlu saya ikuti? Terima kasih sebelumnya, Kak`;
const CH='<svg class="i" viewBox="0 0 24 24" aria-hidden="true"><path d="M7.9 20A9 9 0 1 0 4 16.1L2 22Z"/><path d="M8 12h.01"/><path d="M12 12h.01"/><path d="M16 12h.01"/></svg>';
const pages=[['index.html','Home'],['fitur.html','Fitur'],['talent.html','Talent & Harga'],['review.html','Review'],['blog.html','Blog'],['kontak.html','Kontak']];
const cur=document.body.dataset.page;
const wa=t=>`https://wa.me/${WA}?text=${encodeURIComponent(t)}`;
document.getElementById('site-header').innerHTML=`<div class="wrap nav"><a class="brand" href="index.html"><img src="logo1.png" alt="">ProjectKita</a><nav class="links" id="links">${pages.map(p=>`<a href="${p[0]}" class="${p[0]===cur?'on':''}">${p[1]}</a>`).join('')}</nav><button class="btn btn-o btn-sm" id="install" hidden>Install Aplikasi</button><a class="btn btn-wa btn-sm" data-wa="${TPL}">${CH} Chat WhatsApp</a><button class="menu" aria-label="Menu" onclick="document.getElementById('links').classList.toggle('open')">☰</button></div>`;
document.getElementById('site-footer').innerHTML=`<div class="wrap"><div class="fgrid"><div><a class="brand" href="index.html" style="color:#fff"><img src="logo1.png" alt="">ProjectKita</a><p style="margin:12px 0;font-size:14px;max-width:300px">Marketplace jasa kreatif untuk client dan freelancer Indonesia.</p><p style="font-size:13px">WhatsApp / Telepon: 088214303430<br>Email: projectkita210@gmail.com</p></div><div><h4>Halaman</h4><ul>${pages.map(p=>`<li><a href="${p[0]}">${p[1]}</a></li>`).join('')}</ul></div><div><h4>Sosial media</h4><ul><li><a href="https://www.instagram.com/projectkita_official" target="_blank" rel="noopener">Instagram</a></li><li><a href="https://www.tiktok.com/@projectkitaofficial" target="_blank" rel="noopener">TikTok</a></li><li><a href="https://www.facebook.com/share/195Vwcrp5B/" target="_blank" rel="noopener">Facebook</a></li></ul></div></div><div class="fbot">© 2026 ProjectKita. Hak cipta dilindungi.</div></div><a class="wafloat" data-wa="${TPL}">${CH} Chat WhatsApp</a>`;
document.querySelectorAll('[data-wa]').forEach(a=>{a.href=wa(a.dataset.wa);a.target='_blank';a.rel='noopener'});

if('serviceWorker' in navigator)addEventListener('load',()=>navigator.serviceWorker.register('/sw.js'));
let dp;const ib=document.getElementById('install');
const doInstall=async()=>{if(!dp)return;dp.prompt();await dp.userChoice;dp=null;document.querySelectorAll('[data-install]').forEach(b=>b.hidden=true)};
addEventListener('beforeinstallprompt',e=>{e.preventDefault();dp=e;document.querySelectorAll('#install,[data-install]').forEach(b=>{b.hidden=false;b.onclick=doInstall})});
addEventListener('appinstalled',()=>document.querySelectorAll('#install,[data-install]').forEach(b=>b.hidden=true));
const ios=/iphone|ipad|ipod/i.test(navigator.userAgent);const n=document.getElementById('ios-note');if(n&&ios)n.hidden=false;
